/// <reference path="./plugin.d.ts" />
/// <reference path="./app.d.ts" />

// VikTempest Seanime UI for Seanime 1.2.1: Season Switcher, AniList Custom Ratings and a theme with colour schemes
// in one extension, with a settings page in the sidebar. Built by suite/build.py, edit the sources there.
// Seanime runs init() (hooks) and the $ui.register() callback (everything else) in separate runtimes,
// each from its own source text, so neither can use anything defined outside of it.

// =================================================================================================
// Module: switcher

// Season Switcher for Seanime
//
// Shows every series only once on the home page (library sections and "Continue watching"), and
// adds a dropdown below the title on anime pages that lists every season of the franchise
// (found through the AniList PREQUEL/SEQUEL relations, e.g. The Apothecary Diaries S1, S2, S3).
// Episodes on the info page of an anime you don't have on disk start online streaming when clicked.
// Picking an entry opens that season's page. Your lists are not touched.
//
// UI language: German, English, Spanish, Portuguese, Japanese (setting "language").

function vsInit_switcher() {

    // ---------------------------------------------------------------------------------------------
    // Library merge hooks.
    //
    // Seanime builds the library (home page) from your list entries. These hooks keep only one card
    // per series in each section (e.g. "Currently watching", "Completed") and only one episode per
    // series in "Continue watching". Your lists on AniList are not changed.
    // Hooks run in their own runtime from their source text, so everything they need is inside them.

    // One function for both hooks; Seanime compiles it from its source text, so it must not use
    // anything from outside.
    function vtssMergeHook(e) {
        try {
            let enabled = "yes", keep = "first"
            try {
                enabled = (function(k){var s;try{s=$store.get("vsuite:settings")}catch(e){}if(!s){try{s=$storage.get("vsuite:settings")}catch(e){}}if(!s)return undefined;if(k==="mergeLibrary"&&s.mod_switcher==="off")return "no";var v=s[k];return v===undefined||v===null||v===""?undefined:String(v)})("mergeLibrary") || "yes"
                keep = (function(k){var s;try{s=$store.get("vsuite:settings")}catch(e){}if(!s){try{s=$storage.get("vsuite:settings")}catch(e){}}if(!s)return undefined;if(k==="mergeLibrary"&&s.mod_switcher==="off")return "no";var v=s[k];return v===undefined||v===null||v===""?undefined:String(v)})("mergeKeep") || "first"
            }
            catch (err) {}
            // Library collection (local files) or stream collection (streaming "include in library")
            const lc = e.libraryCollection || e.streamCollection
            if (enabled === "yes" && lc) {
                const ids = []
                ;(lc.lists || []).forEach((list) => (list.entries || []).forEach((entry) => {
                    if (entry && entry.mediaId) ids.push(entry.mediaId)
                }))
                ;(lc.anime || []).forEach((media) => {
                    if (media && media.id) ids.push(media.id)
                })
                ;(lc.continueWatchingList || []).forEach((ep) => {
                    if (ep && ep.baseAnime && ep.baseAnime.id) ids.push(ep.baseAnime.id)
                })

                // Relations (PREQUEL/SEQUEL) of every id, cached for 12 hours and fetched 50 at a time
                const CACHE_MS = 12 * 60 * 60 * 1000
                const rel = {}
                // Several rounds, so seasons are also connected through entries that are not shown here
                // (e.g. Season 1 and 3 in this section, Season 2 somewhere else or not on your list)
                let wanted = ids.slice()
                // Seanime waits for this hook before it shows the home page, and AniList allows
                // only a few requests per minute. So at most 3 requests per call: what is missing
                // gets merged the next time the home page loads.
                let requests = 0
                for (let round = 0; round < 8 && wanted.length; round++) {
                    const missing = []
                    wanted.forEach((id) => {
                        if (rel[id]) return
                        const c = $store.get("vtss:rel:" + id)
                        if (c && c.time && (Date.now() - c.time) < CACHE_MS) rel[id] = c.rel
                        else if (missing.indexOf(id) === -1) missing.push(id)
                    })
                    for (let i = 0; i < missing.length; i += 25) {
                        if (requests >= 3) break
                        requests++
                        const chunk = missing.slice(i, i + 25)
                        try {
                            const res = JSON.parse(JSON.stringify($anilist.customQuery({
                                query: "query ($ids: [Int]) { Page(perPage: 25) { media(id_in: $ids, type: ANIME) { id startDate { year month day } relations { edges { relationType node { id type } } } } } }",
                                variables: { ids: chunk },
                            }, "")))
                            const page = (res && (res.Page || (res.data && res.data.Page))) || {}
                            ;(page.media || []).forEach((m) => {
                                const r = []
                                ;((m.relations && m.relations.edges) || []).forEach((edge) => {
                                    if (edge && edge.node && edge.node.type === "ANIME" &&
                                        (edge.relationType === "PREQUEL" || edge.relationType === "SEQUEL")) r.push(edge.node.id)
                                })
                                rel[m.id] = r
                                const d = m.startDate || {}
                                $store.set("vtss:rel:" + m.id, {
                                    time: Date.now(), rel: r,
                                    start: d.year ? d.year * 10000 + (d.month || 12) * 100 + (d.day || 28) : 99999999,
                                })
                            })
                        }
                        catch (err) {
                            console.warn("season-switcher: could not load relations", err)
                        }
                    }
                    const next = []
                    wanted.forEach((id) => (rel[id] || []).forEach((other) => {
                        if (!rel[other] && next.indexOf(other) === -1) next.push(other)
                    }))
                    wanted = next
                }

                // Union-find: ids connected through PREQUEL/SEQUEL belong to the same series. A movie
                // between two seasons connects them even when it is not on your list.
                const parent = {}
                const find = (x) => {
                    while (parent[x] !== undefined && parent[x] !== x) x = parent[x]
                    return x
                }
                const union = (a, b) => {
                    if (parent[a] === undefined) parent[a] = a
                    if (parent[b] === undefined) parent[b] = b
                    const ra = find(a), rb = find(b)
                    if (ra !== rb) parent[rb] = ra
                }
                Object.keys(rel).forEach((key) => {
                    const id = parseInt(key, 10)
                    if (parent[id] === undefined) parent[id] = id
                    ;(rel[key] || []).forEach((other) => union(id, other))
                })

                const dateKey = (media) => {
                    const d = (media && media.startDate) || {}
                    if (!d.year) return 99999999
                    return d.year * 10000 + (d.month || 12) * 100 + (d.day || 28)
                }

                // Keeps one item per series, at the position of the first one
                const merge = (items, mediaOf, latest) => {
                    const best = {}
                    items.forEach((item, i) => {
                        const media = mediaOf(item)
                        if (!media || !media.id) return
                        const root = find(media.id)
                        const cur = best[root]
                        const k = dateKey(media)
                        if (!cur) best[root] = { i: i, k: k, pos: i }
                        else if (latest ? k > cur.k : k < cur.k) best[root] = { i: i, k: k, pos: cur.pos }
                    })
                    const out = []
                    const byPos = {}
                    Object.keys(best).forEach((root) => {
                        byPos[best[root].pos] = best[root].i
                    })
                    items.forEach((item, i) => {
                        const media = mediaOf(item)
                        if (!media || !media.id) out.push(item)
                        else if (byPos[i] !== undefined) out.push(items[byPos[i]])
                    })
                    return out
                }

                ;(lc.lists || []).forEach((list) => {
                    if (list.entries && list.entries.length > 1) {
                        list.entries = merge(list.entries, (entry) => entry && entry.media, keep === "latest")
                    }
                })
                if (lc.anime && lc.anime.length > 1) {
                    lc.anime = merge(lc.anime, (media) => media, keep === "latest")
                }
                // Continue watching: the earliest season is the one you are actually on
                if (lc.continueWatchingList && lc.continueWatchingList.length > 1) {
                    lc.continueWatchingList = merge(lc.continueWatchingList, (ep) => ep && ep.baseAnime, false)
                }
            }
        }
        catch (err) {
            console.error("season-switcher: library merge failed", err)
        }
        e.next()
    }

    $app.onAnimeLibraryCollection(vtssMergeHook)
    $app.onAnimeLibraryStreamCollection(vtssMergeHook)
}

// =================================================================================================
// Module: ratings

// AniList Custom Ratings for Seanime
//
// Adds a "Custom Rating" section with your AniList Advanced Scoring categories (e.g. Story,
// Characters, Visuals) below Seanime's own list editor. When you click Save, the average becomes
// your score. There is also a "Rate" button on anime and manga pages (and in the media card
// context menu) that opens the same rating in a separate window.
// Existing category scores are loaded from AniList, arrow keys step by 1, 0.5 or 0.1, and the
// overall score is the average of the rated categories, like on AniList. A second button,
// "Custom Lists", assigns the entry to your custom lists. Everything is saved directly to AniList.
//
// UI language: German, English, Spanish, Portuguese, Japanese (plugin setting "language").

function vsInit_ratings() {

    // ---------------------------------------------------------------------------------------------
    // Save hooks for Seanime's own list editor.
    //
    // When you change categories in the "Custom Rating" section of the editor, the plugin stores
    // the pending rating in $store. When you then click Seanime's Save button, these hooks put the
    // average in as your score and save the category scores to AniList.
    // Hooks run in their own runtime, so everything they need is inside them.

    $app.onPreUpdateEntry((e) => {
        try {
            const pending = $store.get("acr:pending:" + e.mediaId)
            const fresh = pending && pending.time && (Date.now() - pending.time) < 30 * 60 * 1000
            if (fresh && pending.scoreRaw !== null && pending.scoreRaw !== undefined) {
                e.scoreRaw = pending.scoreRaw
            }
        }
        catch (err) {
            console.error("anilist-custom-ratings: pre update hook failed", err)
        }
        e.next()
    })

    $app.onPostUpdateEntry((e) => {
        try {
            // The entry changed, so the cached copy is out of date
            $store.set("acr:entry:" + e.mediaId, { time: 0 })

            const key = "acr:pending:" + e.mediaId
            const pending = $store.get(key)
            const fresh = pending && pending.time && (Date.now() - pending.time) < 30 * 60 * 1000
            if (fresh) {
                $store.set(key, { time: 0 })
            }
            // Only the score changed: the pre update hook already saved it, no extra request needed
            if (fresh && pending.advancedScores && pending.advancedScores.length) {
                const token = $database.anilist.getToken()
                if (token) {
                    const variables = { mediaId: e.mediaId, advancedScores: pending.advancedScores }
                    if (pending.scoreRaw !== null && pending.scoreRaw !== undefined) variables.scoreRaw = pending.scoreRaw
                    $anilist.customQuery({
                        query: "mutation ($mediaId: Int, $advancedScores: [Float], $scoreRaw: Int) { SaveMediaListEntry(mediaId: $mediaId, advancedScores: $advancedScores, scoreRaw: $scoreRaw) { id } }",
                        variables: variables,
                    }, token)
                }
            }
        }
        catch (err) {
            console.error("anilist-custom-ratings: saving category scores failed", err)
        }
        e.next()
    })
}

// =================================================================================================
// Module: extras

// -------------------------------------------------------------------------------------------------
// Extras for VikTempest Seanime UI:
//   - screensaver with the anime of the home page banner (trending) after some idle minutes
//   - sleep timer in the tray (pause after X minutes or after this episode)
//   - notice about new seasons of anime on your list
//   - filler episodes dimmed or hidden
//   - right-click menu on episodes
//   - rating window after the last episode of a season
//   - quick search with Ctrl+K
// Built into viktempest-ui.json by suite/build.py. Uses vsTray(), vsTrayHeader(), vsOpenSettings()
// and vsShare from suite/settings.js when they are there.

function vsInit_extras() {
}

// =================================================================================================

function init() {
    vsInit_switcher()
    vsInit_ratings()
    vsInit_extras()
    $ui.register((ctx) => {
    const VS_VERSION = "1.2.1"
    const VS_EXT_ID = "viktempest-ui"
    const VS_TRAY_ICON = "https://raw.githubusercontent.com/vikTempest/custom-ratings-.5-options/main/icon.png"
    const VS_THEME_CSS = "@media (min-width: 1024px) {\n/* =====================================================================\n   SEANIME · \"NETFLIX\"-THEME  (Desktop, ab 1024px)\n   Einfügen unter: Einstellungen → User Interface → Tab \"CSS\" → \"Custom CSS\"\n   Getestet gegen die Selektoren von Seanime Denshi 3.10.4\n   ===================================================================== */\n\n/* ---------- 1. Farben: tiefes Schwarz + Netflix-Rot ------------------ */\n\nhtml, body { background: var(--background) !important; }\nbody { -webkit-font-smoothing: antialiased; letter-spacing: -.005em; }\n::selection { background: rgb(var(--vs-accent-rgb) / .55); color: #fff; }\n\n/* ---------- 2. Typografie: kräftige Netflix-Überschriften ------------ */\n[data-main-layout-content] h1,\n[data-main-layout-content] h2 {\n  font-weight: 800;\n  letter-spacing: -.02em;\n}\n[data-main-layout-content] h3,\n[data-main-layout-content] h4 {\n  font-weight: 700;\n  letter-spacing: -.01em;\n  color: #e5e5e5;\n}\n\n/* ---------- 3. Scrollbalken: dünn & unauffällig --------------------- */\n::-webkit-scrollbar { width: 8px; height: 8px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb { background: rgba(255,255,255,.14); border-radius: 8px; }\n::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,.28); }\n\n/* ---------- 4. Seitenleiste ----------------------------------------- */\n[data-sidebar-navbar-vertical-menu] [data-vertical-menu-item-link],\n[data-sidebar-navbar-vertical-menu] [data-vertical-menu-item-button] {\n  position: relative;\n  transition: color .2s var(--nf-ease), background-color .2s var(--nf-ease);\n}\n[data-vertical-menu-item-link][data-current=true]::before {\n  content: \"\";\n  position: absolute; left: -2px; top: 22%; bottom: 22%;\n  width: 3px; border-radius: 3px;\n  background: var(--nf-red);\n  box-shadow: 0 0 12px rgb(var(--vs-accent-rgb) / .7);\n}\n[data-vertical-menu-item-link][data-current=true] { color: #fff !important; }\n\n/* Obere Leiste: leicht durchsichtig mit Blur wie bei Netflix */\n[data-top-navbar] {\n  background: linear-gradient(180deg, rgba(0,0,0,.75) 0%, rgba(0,0,0,0) 100%);\n}\n\n/* ---------- 5. Anime-Karten (Poster) -------------------------------- */\n[data-media-entry-card-body] {\n  border-radius: 6px !important;\n  overflow: hidden;\n  box-shadow: 0 4px 14px rgba(0,0,0,.45);\n  transition: transform .35s var(--nf-ease), box-shadow .35s var(--nf-ease);\n}\n[data-media-entry-card-container]:hover [data-media-entry-card-body] {\n  transform: translateY(-4px);\n  box-shadow: 0 14px 30px rgba(0,0,0,.7), 0 0 0 2px rgba(255,255,255,.85);\n}\n[data-media-entry-card-body-image] {\n  transition: transform .6s var(--nf-ease) !important;\n}\n[data-media-entry-card-title-section-title] {\n  font-weight: 600 !important;\n  color: #e5e5e5;\n}\n[data-media-entry-card-title-section-year-season] { color: var(--muted); }\n\n/* Hover-Popup: wie die Netflix-Vorschaukarte */\n[data-media-entry-card-hover-popup] {\n  border-radius: 8px !important;\n  border: none !important;\n  background: var(--paper) !important;\n  box-shadow: 0 20px 50px rgba(0,0,0,.85) !important;\n  overflow: hidden;\n}\n[data-media-entry-card-hover-popup-banner-container] { border-radius: 8px 8px 0 0 !important; }\n[data-media-entry-card-hover-popup-title] { font-weight: 700 !important; }\n\n/* Fortschritts-Badges dezenter */\n[data-media-entry-progress-badge] {\n  background: rgba(0,0,0,.72) !important;\n  backdrop-filter: blur(6px);\n}\n[data-media-entry-score-badge] { backdrop-filter: blur(6px); }\n\n/* ---------- 6. Episoden-Karten (\"Weiterschauen\") -------------------- */\n[data-episode-card-image-container] {\n  border-radius: 6px !important;\n  box-shadow: 0 6px 18px rgba(0,0,0,.5);\n  transition: transform .35s var(--nf-ease), box-shadow .35s var(--nf-ease);\n}\n[data-episode-card]:hover [data-episode-card-image-container] {\n  transform: scale(1.04);\n  box-shadow: 0 16px 34px rgba(0,0,0,.75), 0 0 0 2px rgba(255,255,255,.85);\n}\n[data-episode-card-image] { transition: transform .6s var(--nf-ease) !important; }\n[data-episode-card]:hover [data-episode-card-image] { transform: scale(1.05); }\n[data-episode-card-title] { font-weight: 700 !important; letter-spacing: -.01em; }\n[data-episode-card-progress-bar-container] [role=progressbar],\n[data-episode-card-progress-bar-container] > div { border-radius: 0 !important; }\n\n[data-episode-grid-item] { border-radius: 6px; transition: background-color .2s; }\n[data-episode-grid-item-image-container] { border-radius: 6px !important; overflow: hidden; }\n\n/* ---------- 7. Anime-Detailseite: großes Kino-Banner ---------------- */\n[data-media-page-header-banner] {\n  -webkit-mask-image: none !important;\n  mask-image: none !important;\n}\n[data-media-page-header-banner-left-gradient] {\n  background: linear-gradient(90deg, var(--background) 0%, rgb(var(--vs-bg-rgb) / .85) 25%, rgb(var(--vs-bg-rgb) / 0) 65%) !important;\n  opacity: 1 !important;\n}\n[data-media-page-header-banner-bottom-gradient] {\n  background: linear-gradient(0deg, var(--background) 0%, rgb(var(--vs-bg-rgb) / .6) 35%, rgb(var(--vs-bg-rgb) / 0) 70%) !important;\n}\n[data-media-page-header-entry-details-title-container] h1,\n[data-media-page-header-entry-details-title-container] p:first-child {\n  font-weight: 900 !important;\n  letter-spacing: -.03em;\n  text-shadow: 0 2px 18px rgba(0,0,0,.6);\n}\n[data-media-page-header-entry-details-cover-image] {\n  border-radius: 6px !important;\n  box-shadow: 0 18px 40px rgba(0,0,0,.7);\n}\n[data-media-entry-genres-list-item] {\n  background: transparent !important;\n  border: 1px solid rgba(255,255,255,.25) !important;\n  border-radius: 999px !important;\n}\n\n/* Startseiten-/Bibliotheks-Banner weicher ausblenden */\n[data-library-header-banner-bottom-gradient],\n[data-custom-library-banner-bottom-gradient] {\n  background: linear-gradient(0deg, var(--background) 0%, rgb(var(--vs-bg-rgb) / 0) 100%) !important;\n}\n\n/* ---------- 8. Buttons, Tabs, Eingaben ------------------------------ */\nbutton, a { transition: background-color .18s, color .18s, transform .12s; }\nbutton:active { transform: scale(.98); }\n\n[data-anime-entry-page-tabs-container] [role=tab][data-state=active],\n[data-settings-page-tabs] [role=tab][data-state=active] {\n  color: #fff !important;\n  box-shadow: inset 0 -2px 0 var(--nf-red);\n}\n\ninput:focus, textarea:focus, select:focus { --tw-ring-color: rgb(var(--vs-accent-rgb) / .6) !important; }\n\n/* Popover, Menüs, Dialoge */\n[role=dialog], [role=menu], [data-radix-popper-content-wrapper] > * {\n  border-color: rgba(255,255,255,.08) !important;\n}\n[role=dialog] { box-shadow: 0 30px 80px rgba(0,0,0,.85) !important; }\n\n/* Toasts */\n[data-sonner-toast] {\n  background: var(--paper-lighter) !important;\n  border: 1px solid rgba(255,255,255,.08) !important;\n}\n\n/* ---------- 9. \"Weiterschauen\" kompakter ---------------------------- */\n[data-continue-watching-container] .UI-Carousel__item {\n  flex-basis: 25% !important;              /* 4 Karten */\n}\n@media (min-width: 1536px) {\n  [data-continue-watching-container] .UI-Carousel__item { flex-basis: 20% !important; }      /* 5 */\n}\n@media (min-width: 2000px) {\n  [data-continue-watching-container] .UI-Carousel__item { flex-basis: 16.666% !important; }  /* 6 */\n}\n[data-continue-watching-container] [data-episode-card-title] { font-size: .9rem !important; }\n[data-continue-watching-container] [data-episode-card-subtitle],\n[data-continue-watching-container] [data-episode-card-meta-text] { font-size: .8rem !important; }\n\n/* ---------- 10. Ziehbarer Slider statt Klick-Punkte ----------------- */\n/* Die Karussells scrollen jetzt nativ: unten erscheint ein schmaler\n   Balken, den man mit der Maus ziehen kann. Die Punkte sind ausgeblendet. */\n.UI-Carousel__content {\n  overflow-x: auto !important;\n  overflow-y: hidden !important;\n  scroll-behavior: smooth;\n  padding-bottom: 14px;                     /* Platz für den Balken */\n  scrollbar-width: thin;\n  scrollbar-color: rgba(255,255,255,.25) transparent;\n}\n.UI-Carousel__content > .UI-Carousel__innerContent {\n  transform: none !important;               /* alte Klick-Animation aus */\n}\n.UI-Carousel__content::-webkit-scrollbar { height: 6px; }\n.UI-Carousel__content::-webkit-scrollbar-track {\n  background: rgba(255,255,255,.06);\n  border-radius: 6px;\n  margin: 0 1rem;\n}\n.UI-Carousel__content::-webkit-scrollbar-thumb {\n  background: rgba(255,255,255,.3);\n  border-radius: 6px;\n}\n.UI-Carousel__content:hover::-webkit-scrollbar { height: 9px; }\n.UI-Carousel__content::-webkit-scrollbar-thumb:hover,\n.UI-Carousel__content::-webkit-scrollbar-thumb:active { background: var(--nf-red); }\n\n/* Punkte und Pfeile über dem Karussell ausblenden */\n.UI-Carousel__root > .absolute.right-0 { display: none !important; }\n\n/* ---------- 11. Tablets quer & Touch-Geräte (ab 1024px, ohne Maus) -- */\n/* Kein \"hängenbleibender\" Hover-Zoom nach dem Antippen, Karussells\n   werden gewischt statt am Balken gezogen. */\n@media (hover: none) {\n  [data-media-entry-card-container]:hover [data-media-entry-card-body] {\n    transform: none;\n    box-shadow: 0 4px 14px rgba(0,0,0,.45);\n  }\n  [data-episode-card]:hover [data-episode-card-image-container] {\n    transform: none;\n    box-shadow: 0 6px 18px rgba(0,0,0,.5);\n  }\n  [data-episode-card]:hover [data-episode-card-image] { transform: none; }\n  .UI-Carousel__content { padding-bottom: 0; scrollbar-width: none; }\n  .UI-Carousel__content::-webkit-scrollbar { display: none; }\n  input, select, textarea { font-size: 16px !important; }\n}\n\n}\n@media (max-width: 1023.98px) {\n/* =====================================================================\n   SEANIME · \"NETFLIX\"-THEME  (Handy & Tablet hochkant, unter 1024px)\n   Einfügen unter: Einstellungen → User Interface → Tab \"CSS\" → \"Mobile custom CSS\"\n   Danach auf dem Handy selbst einmal speichern (siehe README).\n   Getestet gegen die Selektoren von Seanime Denshi 3.10.4\n   ===================================================================== */\n\n/* ---------- 1. Farben: tiefes Schwarz + Netflix-Rot ------------------ */\n\nhtml, body { background: var(--background) !important; }\nbody {\n  -webkit-font-smoothing: antialiased;\n  -webkit-tap-highlight-color: transparent;   /* kein grauer Kasten beim Antippen */\n}\n::selection { background: rgb(var(--vs-accent-rgb) / .55); color: #fff; }\n\n/* ---------- 2. Überschriften --------------------------------------- */\n[data-main-layout-content] h1,\n[data-main-layout-content] h2 { font-weight: 800; letter-spacing: -.02em; }\n[data-main-layout-content] h3,\n[data-main-layout-content] h4 { font-weight: 700; letter-spacing: -.01em; color: #e5e5e5; }\n\n/* ---------- 3. Obere Leiste und Menü -------------------------------- */\n[data-top-navbar] {\n  background: linear-gradient(180deg, rgba(0,0,0,.8) 0%, rgba(0,0,0,0) 100%);\n}\n[data-vertical-menu-item-link][data-current=true] { color: #fff !important; }\n\n/* ---------- 4. Anime-Karten (Poster) -------------------------------- */\n[data-media-entry-card-body] {\n  border-radius: 6px !important;\n  overflow: hidden;\n  box-shadow: 0 4px 14px rgba(0,0,0,.45);\n  transition: transform .12s;\n}\n/* Kurzes Eindrücken beim Antippen statt Hover-Effekt */\n[data-media-entry-card-container]:active [data-media-entry-card-body] { transform: scale(.97); }\n[data-media-entry-card-title-section-title] { font-weight: 600 !important; color: #e5e5e5; }\n[data-media-entry-card-title-section-year-season] { color: var(--muted); }\n[data-media-entry-progress-badge] { background: rgba(0,0,0,.72) !important; }\n\n/* ---------- 5. Episoden-Karten (\"Weiterschauen\") -------------------- */\n[data-episode-card-image-container] {\n  border-radius: 6px !important;\n  box-shadow: 0 6px 18px rgba(0,0,0,.5);\n  transition: transform .12s;\n}\n[data-episode-card]:active [data-episode-card-image-container] { transform: scale(.97); }\n[data-episode-card-title] { font-weight: 700 !important; }\n[data-episode-card-progress-bar-container] [role=progressbar],\n[data-episode-card-progress-bar-container] > div { border-radius: 0 !important; }\n\n/* Folgenliste auf der Anime-Seite: Rückmeldung beim Antippen */\n[data-episode-grid-item] { border-radius: 6px; }\n[data-episode-grid-item]:active { background: rgba(255,255,255,.06); }\n[data-episode-grid-item-image-container] { border-radius: 6px !important; overflow: hidden; }\n\n/* ---------- 6. Anime-Detailseite ------------------------------------ */\n[data-media-page-header-banner-bottom-gradient] {\n  background: linear-gradient(0deg, var(--background) 0%, rgb(var(--vs-bg-rgb) / .6) 40%, rgb(var(--vs-bg-rgb) / 0) 75%) !important;\n}\n[data-media-page-header-entry-details-title-container] h1,\n[data-media-page-header-entry-details-title-container] p:first-child {\n  font-weight: 900 !important;\n  letter-spacing: -.03em;\n  text-shadow: 0 2px 14px rgba(0,0,0,.6);\n}\n[data-media-page-header-entry-details-cover-image] {\n  border-radius: 6px !important;\n  box-shadow: 0 12px 30px rgba(0,0,0,.7);\n}\n[data-media-entry-genres-list-item] {\n  background: transparent !important;\n  border: 1px solid rgba(255,255,255,.25) !important;\n  border-radius: 999px !important;\n}\n[data-library-header-banner-bottom-gradient],\n[data-custom-library-banner-bottom-gradient] {\n  background: linear-gradient(0deg, var(--background) 0%, rgb(var(--vs-bg-rgb) / 0) 100%) !important;\n}\n\n/* ---------- 7. Tabs, Eingaben, Dialoge ------------------------------ */\n[data-anime-entry-page-tabs-container] [role=tab][data-state=active],\n[data-settings-page-tabs] [role=tab][data-state=active] {\n  color: #fff !important;\n  box-shadow: inset 0 -2px 0 var(--nf-red);\n}\n\n/* 16px in Eingabefeldern: sonst zoomt das iPhone beim Antippen rein */\ninput, select, textarea { font-size: 16px !important; }\ninput:focus, textarea:focus, select:focus { --tw-ring-color: rgb(var(--vs-accent-rgb) / .6) !important; }\n\n[role=dialog], [role=menu], [data-radix-popper-content-wrapper] > * {\n  border-color: rgba(255,255,255,.08) !important;\n}\n[role=dialog] { box-shadow: 0 30px 80px rgba(0,0,0,.85) !important; }\n[data-sonner-toast] {\n  background: var(--paper-lighter) !important;\n  border: 1px solid rgba(255,255,255,.08) !important;\n}\n\n/* ---------- 8. Karussells: wischen, ohne Scrollbalken --------------- */\n.UI-Carousel__content { scrollbar-width: none; }\n.UI-Carousel__content::-webkit-scrollbar { display: none; }\n\n}\n"

    // -------------------------------------------------------------------------------------------------
    // VikTempest Seanime UI: settings page, theme with colour schemes and module loader.
    //
    // All settings live in $storage under "vsuite:settings" and are mirrored to $store so the hooks
    // (which run in their own runtime) can read them too. The modules read them through the same
    // function that used to be $getUserPreference (build.py swaps the calls), so they always see the
    // current value: everything that is read when it is used works right away, without a restart.
    // The settings page is a webview in its own screen with an entry in Seanime's sidebar.
    // VS_VERSION and VS_THEME_CSS are added in front of this file by build.py.

    const VS_SETTINGS_KEY = "vsuite:settings"
    const VS_THEME_ASKED_KEY = "vsuite:themeAsked"
    const VS_HEALTH_KEY = "vsuite:health"

    // Module UI setup functions, added by the modules through vsRegister() while init() runs
    const vsModules = []

    function vsRegister(name, fn) {
        vsModules.push({ name: name, fn: fn })
    }

    // The tray icon (top bar) is the way into the settings: Seanime only shows the sidebar entry
    // after the sidebar is loaded again, so after installing it is missing until a reload.
    // A plugin has one tray, so a module that wants its own tray content asks for it here.
    let vsTrayState = { ctx: null, tray: null, header: null }

    // Shared between the parts: extra tray sections, the rating window, whether the colour picker is open
    const vsShare = { traySections: [], rate: null, pickerOpen: false }

    function vsOpenSettings() {
        try { vsTrayState.ctx.screen.navigateTo("/webview", { id: VS_EXT_ID }) }
        catch (e) { console.warn("viktempest-ui: could not open settings", e) }
    }

    // Returns the shared tray. Its content starts with the title and an "open settings" button.
    function vsTray(opts) {
        const ctx = vsTrayState.ctx
        if (!vsTrayState.tray) {
            vsTrayState.tray = ctx.newTray(Object.assign({
                iconUrl: VS_TRAY_ICON,
                tooltipText: "VikTempest Seanime UI",
                withContent: true,
                width: "24rem",
            }, opts || {}))
        }
        return vsTrayState.tray
    }

    // The tray is drawn often: its render function only builds components, everything else
    // (language, click handlers) is prepared once here.
    function vsTrayHeader(tray) {
        if (!vsTrayState.header) {
            const lang = vsLoadSettings().language === "de" ? "de" : "en"
            vsTrayState.header = {
                label: VS_PAGE_TEXT[lang].openSettings,
                onClick: vsTrayState.ctx.eventHandler("vs-open-settings", () => vsOpenSettings()),
            }
        }
        const h = vsTrayState.header
        return [
            tray.text("VikTempest Seanime UI", { className: "font-semibold text-lg" }),
            tray.button(h.label, { intent: "primary", size: "sm", onClick: h.onClick }),
        ].concat(vsTraySections(tray))
    }

    function vsTraySections(tray) {
        let out = []
        vsShare.traySections.forEach((fn) => {
            try { out = out.concat(fn(tray) || []) } catch (e) { console.warn("viktempest-ui: tray section", e) }
        })
        return out
    }

    // Modules call this when they find a part of Seanime's page they work with, so the settings page
    // can show whether everything still works after a Seanime update.
    function vsHealth(name) {
        try {
            const h = $store.get(VS_HEALTH_KEY) || {}
            if (h[name] && Date.now() - h[name] < 60000) return
            h[name] = Date.now()
            $store.set(VS_HEALTH_KEY, h)
        }
        catch (e) {}
    }

    // -------------------------------------------------------------------------------------------------
    // Colour schemes

    const VS_SCHEMES = {
        red: { accent: "#e50914", bg: "#0f0f0f" },
        purple: { accent: "#8b5cf6", bg: "#111016" },
        blue: { accent: "#3b9eff", bg: "#0a111d" },
    }

    function vsHexRgb(hex) {
        let h = String(hex || "").trim().replace("#", "")
        if (h.length === 3) h = h.split("").map((c) => c + c).join("")
        if (!/^[0-9a-fA-F]{6}$/.test(h)) return null
        const n = parseInt(h, 16)
        return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
    }

    function vsMix(a, b, t) {
        return a.map((v, i) => Math.round(v + (b[i] - v) * t))
    }

    // The two colours of the chosen scheme, or null when the theme is off
    function vsSchemeColors(s) {
        if (!s || !s.theme || s.theme === "off") return null
        if (s.theme === "custom") {
            return {
                accent: vsHexRgb(s.themeAccent) || vsHexRgb(VS_SCHEMES.red.accent),
                bg: vsHexRgb(s.themeBg) || vsHexRgb(VS_SCHEMES.red.bg),
            }
        }
        const sc = VS_SCHEMES[s.theme] || VS_SCHEMES.red
        return { accent: vsHexRgb(sc.accent), bg: vsHexRgb(sc.bg) }
    }

    // Seanime's colour variables for a scheme. The rest of the theme (VS_THEME_CSS) only uses these.
    function vsPaletteCss(colors) {
        const a = colors.accent, bg = colors.bg
        const W = [255, 255, 255], B = [0, 0, 0]
        const sp = (c) => c.join(" ")
        const rgb = (c) => "rgb(" + c.join(",") + ")"
        const scale = [
            ["50", vsMix(a, W, .92)], ["100", vsMix(a, W, .84)], ["200", vsMix(a, W, .66)], ["300", vsMix(a, W, .4)],
            ["400", vsMix(a, W, .2)], ["500", a], ["600", vsMix(a, B, .13)], ["700", vsMix(a, B, .28)],
            ["800", vsMix(a, B, .44)], ["900", vsMix(a, B, .6)], ["950", vsMix(a, B, .76)],
        ]
        const paper = vsMix(bg, W, .035)
        return ":root, .dark, [data-mode=dark] {\n" +
            scale.map((s) => "  --color-brand-" + s[0] + ": " + sp(s[1]) + " !important;").join("\n") + "\n" +
            "  --background: " + rgb(bg) + " !important;\n" +
            "  --paper: " + rgb(paper) + " !important;\n" +
            "  --paper-lighter: " + rgb(vsMix(bg, W, .063)) + " !important;\n" +
            "  --media-card-popup-background: " + rgb(paper) + " !important;\n" +
            "  --hover-from-background-color: " + rgb(vsMix(bg, W, .09)) + " !important;\n" +
            "  --border: rgba(255,255,255,.08) !important;\n" +
            "  --muted: rgba(255,255,255,.55) !important;\n" +
            "  --muted-highlight: rgba(255,255,255,.75) !important;\n" +
            "  --subtle: rgba(255,255,255,.05) !important;\n" +
            "  --subtle-highlight: rgba(255,255,255,.09) !important;\n" +
            "  --ring: " + rgb(a) + " !important;\n" +
            "  --nf-red: " + rgb(a) + ";\n" +
            "  --nf-ease: cubic-bezier(.2,.8,.2,1);\n" +
            "  --vs-accent-rgb: " + sp(a) + ";\n" +
            "  --vs-bg-rgb: " + sp(bg) + ";\n" +
            "}\n" +
            "@media (min-width: 1024px) { :root, .dark, [data-mode=dark] { --radius: .375rem; --radius-md: .375rem; } }\n"
    }

    function vsAccentHex(s) {
        const c = vsSchemeColors(s)
        if (!c) return ""
        return "#" + c.accent.map((v) => (v < 16 ? "0" : "") + v.toString(16)).join("")
    }

    // -------------------------------------------------------------------------------------------------
    // Settings

    // Settings shown on the page.
    //   restart: the change is used after Seanime restarts
    //   live:    saved and applied as soon as it is changed (no Save button needed)
    //   showIf:  only shown when another setting has this value
    const VS_FIELDS = [
        {
            section: "general", fields: [
                { key: "language", restart: true, default: "de", label: { de: "Sprache", en: "Language" },
                  options: [["de", "Deutsch"], ["en", "English"], ["es", "Español"], ["pt", "Português"], ["ja", "日本語"]],
                  hint: { de: "Gilt für alle Teile.", en: "Used by every part." } },
                { key: "mod_switcher", restart: true, default: "on", label: { de: "Season Switcher", en: "Season Switcher" }, onOff: true,
                  hint: { de: "Staffeln zusammenfassen, Staffel-Dropdown, Folgenliste", en: "Merge seasons, season dropdown, episode list" } },
                { key: "mod_ratings", restart: true, default: "on", label: { de: "AniList Custom Ratings", en: "AniList Custom Ratings" }, onOff: true,
                  hint: { de: "Bewertungskategorien und Custom Lists", en: "Rating categories and custom lists" } },
                { key: "mod_extras", restart: true, default: "on", label: { de: "Extras", en: "Extras" }, onOff: true,
                  hint: { de: "Bildschirmschoner, Schlaftimer, neue Staffeln, Filler, Schnellsuche", en: "Screensaver, sleep timer, new seasons, filler, quick search" } },
            ],
        },
        {
            section: "theme", fields: [
                { key: "theme", live: true, default: "off", label: { de: "Farbschema", en: "Colour scheme" }, seg: true,
                  options: [["off", { de: "Aus", en: "Off" }], ["red", { de: "Rot", en: "Red" }], ["purple", { de: "Lila", en: "Purple" }],
                            ["blue", { de: "Blau", en: "Blue" }], ["custom", { de: "Eigene", en: "Custom" }]],
                  hint: { de: "Wirkt sofort. Hast du das Theme früher unter Custom CSS eingefügt, lösch es dort.",
                          en: "Applies right away. If you pasted the theme into Custom CSS before, remove it there." } },
                { key: "themeAccent", live: true, default: "#e50914", color: true, showIf: ["theme", "custom"],
                  label: { de: "Akzentfarbe", en: "Accent colour" }, hint: { de: "Knöpfe, Fortschritt, Markierungen", en: "Buttons, progress, highlights" } },
                { key: "themeBg", live: true, default: "#0f0f0f", color: true, showIf: ["theme", "custom"],
                  label: { de: "Hintergrund", en: "Background" }, hint: { de: "Am besten eine sehr dunkle Farbe", en: "A very dark colour works best" } },
            ],
        },
        {
            section: "switcher", fields: [
                { key: "titleLanguage", default: "english", label: { de: "Titel", en: "Titles" },
                  options: [["english", "English"], ["romaji", "Romaji"], ["native", "Native / 日本語"]] },
                { key: "includeExtras", default: "no", label: { de: "Filme, OVAs und Specials im Dropdown", en: "Movies, OVAs and specials in the dropdown" }, yesNo: true },
                { key: "showProgress", default: "yes", label: { de: "Fortschritt im Staffel-Dropdown", en: "Progress in the season dropdown" }, yesNo: true,
                  hint: { de: "z. B. „✓“ für fertig oder „5/12“", en: "e.g. \"✓\" when finished or \"5/12\"" } },
                { key: "mergeLibrary", default: "yes", label: { de: "Staffeln auf der Startseite zusammenfassen", en: "Merge seasons on the home page" }, yesNo: true },
                { key: "mergeKeep", default: "first", label: { de: "Welche Karte pro Serie", en: "Card to show per series" },
                  options: [["first", { de: "Erste Staffel", en: "First season" }], ["latest", { de: "Neueste Staffel", en: "Latest season" }]] },
                { key: "seasonBadge", default: "yes", label: { de: "Abzeichen „X Staffeln“ auf der Startseite", en: "\"X seasons\" badge on the home page" }, yesNo: true },
                { key: "infoPage", restart: true, default: "yes", label: { de: "Anime-Seiten mit Folgenliste öffnen, Stream erst beim Klick", en: "Open anime pages on the episode list, stream only on click" }, yesNo: true,
                  hint: { de: "„Nein“ lässt Seanime so, wie es ohne Optimierung ist.", en: "\"No\" leaves Seanime as it is without the optimisation." } },
                { key: "episodeClick", default: "yes", label: { de: "Folge anklicken startet Online-Stream", en: "Click an episode to start online streaming" }, yesNo: true },
            ],
        },
        {
            section: "ratings", fields: [
                { key: "step", default: "1", label: { de: "Schrittweite der Pfeiltasten", en: "Arrow key step" },
                  options: [["1", "1"], ["0.5", "0.5"], ["0.1", "0.1"]],
                  hint: { de: "0,5 und 0,1 brauchen auf AniList das Scoring System „10 Point Decimal“.", en: "0.5 and 0.1 need the \"10 Point Decimal\" scoring system on AniList." } },
