                    const v = (function(k){var s;try{s=$store.get("vsuite:settings")}catch(e){}if(!s){try{s=$storage.get("vsuite:settings")}catch(e){}}if(!s)return undefined;if(k==="mergeLibrary"&&s.mod_switcher==="off")return "no";var v=s[k];return v===undefined||v===null||v===""?undefined:String(v)})(key)
