            function t(key) {
                let str = (I18N[LANG] && I18N[LANG][key]) || I18N.en[key] || key
                for (let i = 1; i < arguments.length; i++) {
                    str = str.split("{" + (i - 1) + "}").join(String(arguments[i]))
